+export async function listTools() {
+  return [
+    {
+      name: 'text_transform',
+      description: 'Transform text using uppercase, lowercase, or slug mode.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          text: { type: 'string', description: 'The text to transform.' },
+          mode: {
+            type: 'string',
+            enum: MODES,
+            description: 'Transform mode: uppercase, lowercase, or slug.'
+          },
+          trim: {
+            type: 'boolean',
+            default: true,
+            description: 'Trim surrounding whitespace. Defaults to true.'
+          }
+        },
+        required: ['text', 'mode'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+function slugify(text) {
+  return text
+    .toLowerCase()
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-+|-+$/g, '');
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'text_transform') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+
+  const { text, mode, trim = true, ...rest } = args;
+
+  if (text === undefined) {
+    throw new Error("Missing required argument 'text'");
+  }
+  if (typeof text !== 'string') {
+    throw new Error("Argument 'text' must be a string");
+  }
+  if (mode === undefined) {
+    throw new Error("Missing required argument 'mode'");
+  }
+  if (typeof mode !== 'string' || !MODES.includes(mode)) {
+    throw new Error(
+      `Invalid mode '${mode}'. Must be one of: ${MODES.join(', ')}`
+    );
+  }
+  if (typeof trim !== 'boolean') {
+    throw new Error("Argument 'trim' must be a boolean");
+  }
+  const extra = Object.keys(rest);
+  if (extra.length > 0) {
+    throw new Error(`Unexpected arguments: ${extra.join(', ')}`);
+  }
+
+  let value = text;
+  if (trim) value = value.trim();
+  if (mode === 'uppercase') value = value.toUpperCase();
+  else if (mode === 'lowercase') value = value.toLowerCase();
+  else if (mode === 'slug') value = slugify(value);
+
+  return { content: [{ type: 'text', text: value }] };
